contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 hash, uint256 lockValue) public payable {
        require(lockValue == 1 ether);
        require(address(this).balance >= lockValue + 1 ether);

        uint256 balanceBefore = address(this).balance;

        c.lockInGuess{value: lockValue}(hash);

        uint256 stuckBlock = block.number + 1;

        // The block number checks out: settle would succeed now.
        c.settle();

        bytes32 answer = keccak256(abi.encodePacked(blockhash(stuckBlock)));
        uint256 balanceAfterFirstSettle = address(this).balance;

        if (hash == answer) {
            // Winning guess: exactly 2 ether paid out, no more and no less.
            assert(balanceAfterFirstSettle == balanceBefore - 1 ether + 2 ether);
        } else {
            // Losing guess: nothing paid out.
            assert(balanceAfterFirstSettle == balanceBefore - 1 ether);
        }

        // The lock was cleared regardless of win or loss: a second settle must revert.
        bool reverted;
        try c.settle() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 hash, uint256 lockValue) public payable {
        require(lockValue == 1 ether);
        require(address(this).balance >= lockValue);

        uint256 balanceBefore = address(this).balance;
        uint256 cBalanceBefore = address(c).balance;

        c.lockInGuess{value: lockValue}(hash);

        uint256 stuckBlock = block.number + 1;
        bytes32 expectedAnswer = keccak256(abi.encodePacked(blockhash(stuckBlock)));

        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        uint256 balanceAfter = address(this).balance;
        uint256 cBalanceAfter = address(c).balance;

        bool lockCleared;
        try c.settle() {
            lockCleared = false;
        } catch {
            lockCleared = true;
        }

        // The first settle must have executed (locked after lockInGuess, and enough blocks passed).
        assert(!settleReverted);

        // After settle, the lock is cleared, so a second settle reverts.
        assert(lockCleared);

        // Net Ether movement: exactly 2 ether received iff the guess was correct, otherwise 1 ether spent.
        if (hash == expectedAnswer) {
            assert(balanceAfter == balanceBefore - lockValue + 2 ether);
            assert(cBalanceAfter == cBalanceBefore + lockValue - 2 ether);
        } else {
            assert(balanceAfter == balanceBefore - lockValue);
            assert(cBalanceAfter == cBalanceBefore + lockValue);
        }
    }

    receive() external payable {}
}

