        bytes32 answer = keccak256(abi.encodePacked(blockhash(lockBlock)));
        uint256 balBefore = address(c).balance;
        uint256 selfBefore = address(this).balance;

        c.settle();

        uint256 balAfter = address(c).balance;
        uint256 selfAfter = address(this).balance;

        if (guess == answer) {
            assert(balBefore - balAfter == 2 ether && selfAfter - selfBefore == 2 ether);
        } else {
            assert(balAfter == balBefore && selfAfter == selfBefore);
        }
    }

    receive() external payable {}
}

