    constructor(C _c) { c = _c; }
    function run(bytes32 guess) public payable {
        require(address(this).balance >= 2 ether);
        c.lockInGuess{value: 1 ether}(guess);
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        bool reverted;
        try c.settle() { reverted = false; } catch { reverted = true; }
        assert(!reverted || address(c).balance == beforeC || address(this).balance == beforeThis);
    }
    receive() external payable {}
}

