contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes32 guess) public payable {
        require(address(this).balance >= 1 ether);

        bool lockReverted;
        try c.lockInGuess{value: 1 ether}(guess) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        bool settledReverted;
        try c.settle() {
            settledReverted = false;
        } catch {
            settledReverted = true;
        }

        assert(lockReverted || settledReverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 h1, bytes32 h2, uint amount1, uint amount2) public payable {
        require(amount1 == 1 ether && amount2 == 1 ether);
        require(address(this).balance >= amount1 + amount2);

        c.lockInGuess{value: amount1}(h1);

        bool reverted;
        try c.lockInGuess{value: amount2}(h2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 h) public payable {
        require(address(this).balance >= 1 ether);

        uint256 beforeBalance = address(c).balance;

        c.lockInGuess{value: 1 ether}(h);

        bool settled;
        try c.settle() {
            settled = true;
        } catch {
            settled = false;
        }

        if (settled) {
            assert(address(c).balance == beforeBalance + 1 ether || address(c).balance + 2 ether == beforeBalance + 1 ether);
        } else {
            assert(address(c).balance == beforeBalance + 1 ether);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes32 h) public payable {
        require(address(this).balance >= 1 ether);

        uint256 beforeBalance = address(c).balance;

        c.lockInGuess{value: 1 ether}(h);

        bool settled;
        try c.settle() {
            settled = true;
        } catch {
            settled = false;
        }

        assert(
            (settled && (address(c).balance == beforeBalance + 1 ether || address(c).balance + 1 ether == beforeBalance - 1 ether)) ||
            (!settled && address(c).balance == beforeBalance + 1 ether)
        );
    }

    receive() external payable {}
}

